// Canvas drawing of captions and text layers, mirroring the ASS generated by
// shared/captions.ts so the preview matches the libass render.
import type { CaptionStyle, Clip } from "../../shared/types";
import { type CaptionPage, captionY, scaleRef } from "../../shared/captions";
import { fontById } from "../../shared/presets";
import { clipDuration } from "../../shared/timeline";

const LINE = 1.22;

function rgba(hex: string, alpha = 1) {
  const h = hex.replace("#", "");
  const r = parseInt(h.slice(0, 2), 16);
  const g = parseInt(h.slice(2, 4), 16);
  const b = parseInt(h.slice(4, 6), 16);
  return `rgba(${r},${g},${b},${alpha})`;
}

function textWithOutline(ctx: CanvasRenderingContext2D, text: string, x: number, y: number, fill: string, outline: number, outlineColor: string, shadow: number) {
  if (shadow > 0) {
    ctx.fillStyle = "rgba(0,0,0,0.5)";
    if (outline > 0) {
      ctx.lineWidth = outline * 2;
      ctx.strokeStyle = "rgba(0,0,0,0.5)";
      ctx.strokeText(text, x + shadow, y + shadow);
    }
    ctx.fillText(text, x + shadow, y + shadow);
  }
  if (outline > 0) {
    ctx.lineWidth = outline * 2;
    ctx.strokeStyle = outlineColor;
    ctx.lineJoin = "round";
    ctx.strokeText(text, x, y);
  }
  ctx.fillStyle = fill;
  ctx.fillText(text, x, y);
}

export function drawCaptions(ctx: CanvasRenderingContext2D, pages: CaptionPage[], t: number, st: CaptionStyle, W: number, H: number) {
  const page = pages.find((p) => t >= p.start && t < p.end);
  if (!page) return;
  const k = scaleRef(W, H);
  const font = fontById(st.font);
  const size = st.size * k;
  ctx.save();
  ctx.font = `${font.bold ? "bold " : ""}${size}px "${font.css}"`;
  ctx.textBaseline = "middle";
  ctx.textAlign = "left";
  const words = page.words;
  let ai = -1;
  for (let i = 0; i < words.length; i++) if (t >= (i === 0 ? page.start : words[i].start)) ai = i;
  const perWord = (st.animation !== "none" && st.animation !== "fade") || st.highlightMode !== "none";
  if (!perWord) ai = -1;
  const sliceStart = ai <= 0 ? page.start : words[ai].start;
  const since = (t - sliceStart) * 1000;
  // page-level animation
  let pageScale = 1;
  let alpha = 1;
  if (st.animation === "bounce" && ai <= 0) {
    const ms = (t - page.start) * 1000;
    pageScale = ms < 90 ? 0.8 + (0.32 * ms) / 90 : ms < 170 ? 1.12 - (0.12 * (ms - 90)) / 80 : 1;
  }
  if (st.animation === "fade") {
    const a = (t - page.start) * 1000;
    const b = (page.end - t) * 1000;
    alpha = Math.min(1, a / 120, b / 100);
  }
  ctx.globalAlpha = Math.max(0, alpha);
  const cx = W / 2;
  const cy = captionY(st, W, H) * H;
  const space = ctx.measureText(" ").width;
  const activeScale = (j: number) => {
    if (j !== ai || !(st.animation === "pop" || st.animation === "wordByWord")) return 1;
    return since < 110 ? 1.25 - (0.19 * since) / 110 : 1.06;
  };
  let idx = 0;
  const lines = page.lines.map((line) =>
    line.map((w) => {
      const j = idx++;
      const s = activeScale(j);
      return { w, j, s, width: ctx.measureText(w.text).width * s };
    })
  );
  const lineH = size * LINE;
  const totalH = lineH * lines.length;
  ctx.translate(cx, cy);
  ctx.scale(pageScale, pageScale);
  lines.forEach((line, li) => {
    const lw = line.reduce((a, x) => a + x.width, 0) + space * (line.length - 1);
    let x = -lw / 2;
    const y = -totalH / 2 + lineH * (li + 0.5);
    if (st.background) {
      const pad = Math.round(size * 0.22);
      ctx.fillStyle = rgba(st.backgroundColor, st.backgroundOpacity);
      ctx.fillRect(x - pad, y - size * 0.62 - pad, lw + pad * 2, size * 1.24 + pad * 2);
    }
    for (const it of line) {
      const hidden = st.animation === "wordByWord" && ai >= 0 && it.j > ai;
      if (!hidden) {
        let color = st.color;
        if (st.animation === "karaoke" && ai >= 0) color = it.j <= ai ? st.highlightColor : st.color;
        else if (it.j === ai && st.highlightMode === "color") color = st.highlightColor;
        if (it.j === ai && st.highlightMode === "box") {
          const pad = size * 0.14;
          ctx.fillStyle = st.highlightColor;
          roundRect(ctx, x - pad, y - size * 0.62 - pad, it.width + pad * 2, size * 1.24 + pad * 2, size * 0.12);
          ctx.fill();
        }
        ctx.save();
        ctx.translate(x + it.width / 2, y);
        ctx.scale(it.s, it.s);
        textWithOutline(ctx, it.w.text, -it.width / it.s / 2, 0, color, st.background ? 0 : st.outline * k, st.outlineColor, st.shadow * k);
        ctx.restore();
      }
      x += it.width + space;
    }
  });
  ctx.restore();
}

function roundRect(ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, r: number) {
  ctx.beginPath();
  ctx.moveTo(x + r, y);
  ctx.arcTo(x + w, y, x + w, y + h, r);
  ctx.arcTo(x + w, y + h, x, y + h, r);
  ctx.arcTo(x, y + h, x, y, r);
  ctx.arcTo(x, y, x + w, y, r);
  ctx.closePath();
}

export function drawTextClip(ctx: CanvasRenderingContext2D, c: Clip, local: number, W: number, H: number) {
  const d = c.text;
  if (!d) return;
  const st = d.style;
  const k = scaleRef(W, H);
  const dur = clipDuration(c);
  const ms = local * 1000;
  const font = fontById(st.font);
  const size = st.size * k;
  let x = d.x * W;
  let y = d.y * H;
  // \fad
  const fin = d.animIn === "none" ? 0 : 220;
  const fout = d.animOut === "none" ? 0 : Math.min(220, Math.max(0, dur * 1000 - fin));
  let alpha = 1;
  if (fin && ms < fin) alpha = ms / fin;
  if (fout && dur * 1000 - ms < fout) alpha = Math.min(alpha, (dur * 1000 - ms) / fout);
  let scale = 1;
  if (d.animIn === "pop") scale = ms < 180 ? 0.4 + (0.68 * ms) / 180 : ms < 300 ? 1.08 - (0.08 * (ms - 180)) / 120 : 1;
  if (d.animIn === "slideUp" && ms < 300) y += W * 0.03 * (1 - ms / 300);
  if (d.animIn === "slideLeft" && ms < 300) x -= W * 0.08 * (1 - ms / 300);
  ctx.save();
  ctx.globalAlpha = Math.max(0, Math.min(1, alpha));
  ctx.translate(x, y);
  if (d.rotation) ctx.rotate((d.rotation * Math.PI) / 180);
  ctx.scale(scale, scale);
  const sw = Math.max(2, d.w * W);
  const sh = Math.max(2, d.h * H);
  switch (d.template) {
    case "arrow": {
      ctx.fillStyle = st.accent;
      ctx.beginPath();
      const pts = [
        [0, sh / 3],
        [sw * 0.62, sh / 3],
        [sw * 0.62, 0],
        [sw, sh / 2],
        [sw * 0.62, sh],
        [sw * 0.62, (2 * sh) / 3],
        [0, (2 * sh) / 3],
      ];
      pts.forEach(([px, py], i) => (i ? ctx.lineTo(px - sw / 2, py - sh / 2) : ctx.moveTo(px - sw / 2, py - sh / 2)));
      ctx.closePath();
      ctx.fill();
      break;
    }
    case "highlightBox": {
      ctx.strokeStyle = st.accent;
      ctx.lineWidth = Math.max(1, st.outline * k) * 2;
      ctx.strokeRect(-sw / 2, -sh / 2, sw, sh);
      break;
    }
    case "progressBar": {
      ctx.restore();
      ctx.save();
      const left = d.x * W - sw / 2;
      const top = d.y * H - sh / 2;
      ctx.fillStyle = "rgba(255,255,255,0.31)";
      ctx.fillRect(left, top, sw, sh);
      ctx.fillStyle = st.accent;
      ctx.fillRect(left, top, sw * Math.min(1, local / Math.max(0.01, dur)), sh);
      break;
    }
    default: {
      const txt = st.uppercase ? d.text.toUpperCase() : d.text;
      ctx.font = `${font.bold ? "bold " : ""}${size}px "${font.css}"`;
      ctx.textBaseline = "middle";
      const boxed = st.background || d.template === "lowerThird" || d.template === "callout";
      const left = d.template === "lowerThird";
      ctx.textAlign = left ? "left" : "center";
      const lines = txt.split("\n");
      const lh = size * LINE;
      lines.forEach((ln, i) => {
        const ly = (i - (lines.length - 1) / 2) * lh;
        const w = ctx.measureText(ln).width;
        if (boxed) {
          const pad = Math.round(size * 0.3);
          ctx.fillStyle = st.accent;
          ctx.fillRect((left ? 0 : -w / 2) - pad, ly - size * 0.62 - pad, w + pad * 2, size * 1.24 + pad * 2);
        }
        textWithOutline(ctx, ln, 0, ly, st.color, boxed ? 0 : st.outline * k, "#000000", st.shadow * k);
      });
      if (left && d.subtitle) {
        const sub = fontById("inter-medium");
        const ss = size * 0.6;
        ctx.font = `${ss}px "${sub.css}"`;
        const sy = size * 1.15;
        const w = ctx.measureText(d.subtitle).width;
        const pad = Math.round(size * 0.22);
        ctx.fillStyle = "rgba(17,17,17,0.85)";
        ctx.fillRect(-pad, sy - ss * 0.62 - pad, w + pad * 2, ss * 1.24 + pad * 2);
        ctx.fillStyle = "#ffffff";
        ctx.fillText(d.subtitle, 0, sy);
      }
    }
  }
  ctx.restore();
}
